{"file_path":"src/address.js","content":"/**
 * Cell addresses. A column is one or two letters, `A` to `Z` then `AA` to
 * `ZZ`, and a row is one to three digits naming a row of at least 1.
 */

const ADDRESS = /^([A-Z]{1,2})([0-9]{1,3})$/

/**
 * Reads an already upper-cased word as an address. Returns null when the word
 * is not an address inside the addressable range.
 */
export function parseAddress(word) {
  const m = ADDRESS.exec(word)
  if (m === null) return null
  const row = Number(m[2])
  if (row < 1) return null
  let col = 0
  for (const ch of m[1]) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, key: m[1] + String(row) }
}

/** The letters naming a column, counting from 1. */
export function columnName(col) {
  let name = ''
  let n = col
  while (n > 0) {
    const rem = (n - 1) % 26
    name = String.fromCharCode(65 + rem) + name
    n = (n - rem - 1) / 26
  }
  return name
}

/** The canonical text of a column and row pair. */
export function addressKey(col, row) {
  return columnName(col) + String(row)
}

/** Orders two cells by column and then by row. */
export function compareCells(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

