{"file_path":"src/values.js","content":"/** Values: a number, text, a boolean, or an error. */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')
export const ZERO = num(0)

export const isError = (v) => v.t === 'err'

/** A value read in an arithmetic position: text is the value error. */
export function toNumber(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'err') return v
  return VALUE
}

/** Any arithmetic result that is not finite is the division error. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : DIV0
}

/** Compares two texts by code point. */
function compareText(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0)
    const q = y[i].codePointAt(0)
    if (p !== q) return p < q ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

const rank = (v) => (v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2)

/** Orders two non-error values: numbers below texts below booleans. */
export function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (ra === 1) return compareText(a.v, b.v)
  const x = a.v ? 1 : 0
  const y = b.v ? 1 : 0
  return x - y
}

/** A number as JavaScript prints it once rounded to ten significant digits. */
export function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

/** The printed form of a value. */
export function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'text') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}
"}

