{"file_path":"src/formula.js","content":"/**
 * The formula grammar. `parseFormula` returns a syntax tree, or null when the
 * grammar does not accept the body.
 */

import { parseAddress } from './address.js'

export const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

const isDigit = (c) => c >= '0' && c <= '9'
const isAlpha = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')

class Failure extends Error {}

const fail = () => {
  throw new Failure()
}

/** Splits a formula body into tokens; spaces and tabs may sit between them. */
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i
      while (j < src.length && isDigit(src[j])) j++
      if (src[j] === '.' && j + 1 < src.length && isDigit(src[j + 1])) {
        j++
        while (j < src.length && isDigit(src[j])) j++
      }
      toks.push({ k: 'num', v: Number(src.slice(i, j)) })
      i = j
      continue
    }
    if (isAlpha(c)) {
      let j = i
      while (j < src.length && isAlpha(src[j])) j++
      while (j < src.length && isDigit(src[j])) j++
      toks.push({ k: 'word', v: src.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      toks.push({ k: 'op', v: two })
      i += 2
      continue
    }
    if ('+-*/^=<>(),:'.includes(c)) {
      toks.push({ k: 'op', v: c })
      i++
      continue
    }
    fail()
  }
  return toks
}

const COMPARISONS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(toks) {
    this.toks = toks
    this.i = 0
  }

  peek() {
    return this.i < this.toks.length ? this.toks[this.i] : null
  }

  isOp(v) {
    const t = this.peek()
    return t !== null && t.k === 'op' && t.v === v
  }

  eat(v) {
    if (!this.isOp(v)) fail()
    this.i++
  }

  expression() {
    let left = this.additive()
    for (;;) {
      const t = this.peek()
      if (t === null || t.k !== 'op' || !COMPARISONS.has(t.v)) return left
      this.i++
      left = { n: 'bin', op: t.v, l: left, r: this.additive() }
    }
  }

  additive() {
    let left = this.multiplicative()
    for (;;) {
      const t = this.peek()
      if (t === null || t.k !== 'op' || (t.v !== '+' && t.v !== '-')) return left
      this.i++
      left = { n: 'bin', op: t.v, l: left, r: this.multiplicative() }
    }
  }

  multiplicative() {
    let left = this.power()
    for (;;) {
      const t = this.peek()
      if (t === null || t.k !== 'op' || (t.v !== '*' && t.v !== '/')) return left
      this.i++
      left = { n: 'bin', op: t.v, l: left, r: this.power() }
    }
  }

  power() {
    const base = this.unary()
    if (this.isOp('^')) {
      this.i++
      return { n: 'bin', op: '^', l: base, r: this.power() }
    }
    return base
  }

  unary() {
    const t = this.peek()
    if (t !== null && t.k === 'op' && (t.v === '-' || t.v === '+')) {
      this.i++
      return { n: 'un', op: t.v, e: this.unary() }
    }
    return this.primary()
  }

  primary() {
    const t = this.peek()
    if (t === null) fail()
    if (t.k === 'num') {
      this.i++
      return { n: 'num', v: t.v }
    }
    if (t.k === 'op' && t.v === '(') {
      this.i++
      const e = this.expression()
      this.eat(')')
      return e
    }
    if (t.k === 'word') {
      this.i++
      if (this.isOp('(')) {
        this.i++
        const args = []
        if (!this.isOp(')')) {
          args.push(this.expression())
          while (this.isOp(',')) {
            this.i++
            args.push(this.expression())
          }
        }
        this.eat(')')
        return { n: 'call', name: t.v, args }
      }
      if (this.isOp(':')) {
        this.i++
        const b = this.peek()
        if (b === null || b.k !== 'word') fail()
        this.i++
        return { n: 'range', a: t.v, b: b.v }
      }
      if (t.v === 'TRUE') return { n: 'bool', v: true }
      if (t.v === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', word: t.v, addr: parseAddress(t.v) }
    }
    return fail()
  }
}

/** Parses a formula body, or returns null when the grammar rejects it. */
export function parseFormula(body) {
  try {
    const parser = new Parser(tokenize(body))
    const ast = parser.expression()
    if (parser.peek() !== null) fail()
    return ast
  } catch (e) {
    if (e instanceof Failure) return null
    throw e
  }
}

/**
 * Whether every range in the tree sits directly as a function argument. A
 * range written anywhere else makes the cell `#ERR!`.
 */
export function rangesWellPlaced(node) {
  if (node.n === 'range') return false
  if (node.n === 'un') return rangesWellPlaced(node.e)
  if (node.n === 'bin') return rangesWellPlaced(node.l) && rangesWellPlaced(node.r)
  if (node.n === 'call') {
    for (const arg of node.args) {
      if (arg.n === 'range') continue
      if (!rangesWellPlaced(arg)) return false
    }
  }
  return true
}
"}

