 * Reads the sheet, in declaration order. Throws a `SheetError` carrying the
 * message a failure writes to standard error.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n]
    let i = 0
    while (i < line.length && isBlank(line[i])) i++
    if (i >= line.length) continue
    if (line[i] === '#') continue

    let j = i
    while (j < line.length && !isBlank(line[j])) j++
    const word = line.slice(i, j).toUpperCase()
    let k = j
    while (k < line.length && isBlank(line[k])) k++
    const content = line.slice(k)

    const addr = parseAddress(word)
    if (addr === null) {
      throw new SheetError(`error: line ${n + 1}: invalid cell address ${word}`)
    }
    if (cells.has(addr.key)) {
      throw new SheetError(`error: line ${n + 1}: cell ${addr.key} is declared twice`)
    }
    cells.set(addr.key, makeCell(addr, content))
  }
  return cells
