  VALUE,
  CYCLE,
  NAME,
  ERR,
  ZERO,
  isError,
  toNumber,
  finite,
  compareValues,
} from './values.js'

const ERRORS = new Set(ERROR_TOKENS)
const NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** The value of a literal: empty is zero, then numbers, errors and text. */
export function literalValue(content) {
  if (content === '') return ZERO
  if (ERRORS.has(content)) return err(content)
  if (NUMBER.test(content)) return num(Number(content))
  return text(content)
}

/** The cells a range covers, by column and then by row, or null. */
function rangeCells(node) {
  const a = parseAddress(node.a)
  const b = parseAddress(node.b)
  if (a === null || b === null) return null
  const c0 = Math.min(a.col, b.col)
  const c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row)
  const r1 = Math.max(a.row, b.row)
  const out = []
  for (let c = c0; c <= c1; c++) {
    for (let r = r0; r <= r1; r++) out.push({ col: c, row: r, key: addressKey(c, r) })
  }
  return out
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.visiting = new Set()
  }

  /** The value of a declared or undeclared cell, given its canonical key. */
  cellValue(key) {
    const cached = this.cache.get(key)
    if (cached !== undefined) return cached
    const cell = this.cells.get(key)
    if (cell === undefined) return ZERO
    if (this.visiting.has(key)) return CYCLE
    this.visiting.add(key)
    let value
    try {
      value = this.evalCell(cell)
    } finally {
      this.visiting.delete(key)
    }
    this.cache.set(key, value)
    return value
  }

  evalCell(cell) {
    if (!cell.formula) return literalValue(cell.content)
    if (cell.ast === null || !cell.wellPlaced) return ERR
    return this.eval(cell.ast)
  }

  eval(node) {
    switch (node.n) {
      case 'num':
        return num(node.v)
      case 'bool':
        return bool(node.v)
      case 'ref':
        return node.addr === null ? REF : this.cellValue(node.addr.key)
      case 'range':
        return ERR
      case 'un':
        return this.evalUnary(node)
      case 'bin':
        return this.evalBinary(node)
      case 'call':
        return this.evalCall(node)
      default:
        return ERR
    }
  }

  evalUnary(node) {
    const v = this.eval(node.e)
    const n = toNumber(v)
    if (isError(n)) return n
    return finite(node.op === '-' ? -n.v : n.v)
  }

  evalBinary(node) {
    const l = this.eval(node.l)
    if (isError(l)) return l
    const r = this.eval(node.r)
    if (isError(r)) return r
    switch (node.op) {
      case '=':
      case '<>':
      case '<':
      case '<=':
      case '>':
      case '>=':
        return this.compare(node.op, l, r)
      default:
        return this.arithmetic(node.op, l, r)
    }
  }

  compare(op, l, r) {
    const c = compareValues(l, r)
    switch (op) {
      case '=':
        return bool(c === 0)
      case '<>':
        return bool(c !== 0)
      case '<':
        return bool(c < 0)
      case '<=':
        return bool(c <= 0)
      case '>':
        return bool(c > 0)
      default:
        return bool(c >= 0)
    }
  }

  arithmetic(op, l, r) {
    const a = toNumber(l)
    if (isError(a)) return a
    const b = toNumber(r)
    if (isError(b)) return b
    switch (op) {
      case '+':
        return finite(a.v + b.v)
      case '-':
        return finite(a.v - b.v)
      case '*':
        return finite(a.v * b.v)
      case '/':
        return b.v === 0 ? DIV0 : finite(a.v / b.v)
      default:
        return finite(a.v ** b.v)
    }
  }

  /** The values an argument contributes, a range giving every cell it covers. */
  argValues(arg) {
    if (arg.n === 'range') {
      const covered = rangeCells(arg)
      if (covered === null) return [REF]
      return covered.map((c) => this.cellValue(c.key))
    }
    return [this.eval(arg)]
  }

  /** One argument read as a single value. */
  scalarArg(arg) {
    const values = this.argValues(arg)
    for (const v of values) if (isError(v)) return v
    return values.length === 1 ? values[0] : ERR
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.has(name)) return NAME
    if (name === 'IF') {
      if (node.args.length !== 3) return ERR
      const cond = this.scalarArg(node.args[0])
      if (isError(cond)) return cond
      let taken
      if (cond.t === 'bool') taken = cond.v
      else if (cond.t === 'num') taken = cond.v !== 0
      else return VALUE
      return this.scalarArg(node.args[taken ? 1 : 2])
    }
    if (name === 'ABS') {
      if (node.args.length !== 1) return ERR
      const v = this.scalarArg(node.args[0])
      const n = toNumber(v)
      if (isError(n)) return n
      return finite(Math.abs(n.v))
    }
    if (node.args.length < 1) return ERR
    const values = []
    for (const arg of node.args) {
      for (const v of this.argValues(arg)) values.push(v)
    }
    for (const v of values) if (isError(v)) return v
    return aggregate(name, values)
  }
}

function aggregate(name, values) {
  if (name === 'COUNT') return num(values.filter((v) => v.t === 'num').length)
  const numbers = []
  for (const v of values) {
    const n = toNumber(v)
    if (isError(n)) return n
    numbers.push(n.v)
  }
  switch (name) {
    case 'SUM': {
      let total = 0
      for (const n of numbers) total += n
      return finite(total)
    }
    case 'AVG': {
      let total = 0
      for (const n of numbers) total += n
      return finite(total / numbers.length)
    }
    case 'MIN': {
      let best = numbers[0]
      for (const n of numbers) if (n < best) best = n
      return finite(best)
    }
    default: {
      let best = numbers[0]
      for (const n of numbers) if (n > best) best = n
      return finite(best)
    }
  }
}

/** The distinct cells a content names directly, ranges expanded, in order. */
export function cellDeps(cell) {
  if (!cell.formula || cell.ast === null) return []
  const seen = new Map()
  const walk = (node) => {
    switch (node.n) {
      case 'ref':
        if (node.addr !== null) seen.set(node.addr.key, node.addr)
        break
      case 'range': {
        const covered = rangeCells(node)
        if (covered !== null) for (const c of covered) seen.set(c.key, c)
        break
      }
      case 'un':
        walk(node.e)
        break
      case 'bin':
        walk(node.l)
        walk(node.r)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }
  walk(cell.ast)
  return [...seen.values()].sort(compareCells)
}
"}

