{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, sortedCells, SheetError } from './sheet.js'
import { Evaluator, cellDeps } from './evaluate.js'
import { formatValue } from './values.js'

function main(argv) {
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    return { code: 2, err: 'error: usage: cli.js values|deps\n' }
  }
  const mode = argv[0]

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) return { code: 2, err: `${e.message}\n` }
    throw e
  }

  const ordered = sortedCells(cells)
  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const cell of ordered) {
      out.push(`${cell.key}=${formatValue(evaluator.cellValue(cell.key))}\n`)
    }
  } else {
    for (const cell of ordered) {
      const deps = cellDeps(cell)
      out.push(`${cell.key}:${deps.map((d) => ` ${d.key}`).join('')}\n`)
    }
  }
  return { code: 0, out: out.join('') }
}

const result = main(process.argv.slice(2))
if (result.err !== undefined) process.stderr.write(result.err)
if (result.out !== undefined && result.out !== '') process.stdout.write(result.out)
process.exit(result.code)
"}

